/**
 * The 3D assets that actually ship.
 *
 * They are generated by `tooling/models/build-models.ts` and copied into `public/models` so the
 * deployment serves them; this test is what keeps the copy honest — a stale copy after a generator
 * change would be a 3D model nobody regenerated, and the byte budget is the product promise that a
 * scene cannot cost more than 2.5 MB.
 */
import { describe, expect, it } from 'bun:test';
import { readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { budgets } from '@nastech/api-contracts';

interface AssetEntry {
  readonly id: string;
  readonly file: string;
  readonly bytes: number;
  readonly clip: string;
  readonly unitsPerMeter: number;
}

const dir = join(import.meta.dir, '..', '..', 'public', 'assets', 'models');

describe('shipped 3D models', () => {
  const manifest = JSON.parse(readFileSync(join(dir, 'manifest.json'), 'utf8')) as { assets: readonly AssetEntry[] };

  it('lists at least the three pilot categories, each with an animation clip', () => {
    expect(manifest.assets.map((a) => a.id)).toEqual(['wristwatch', 'smartphone', 'parka']);
    for (const asset of manifest.assets) {
      expect(asset.clip.length).toBeGreaterThan(0);
      expect(asset.unitsPerMeter).toBe(1);
    }
  });

  it('ships each listed file, at the size the manifest claims, inside the scene budget', () => {
    for (const asset of manifest.assets) {
      const path = join(dir, asset.file);
      expect(statSync(path).size).toBe(asset.bytes);
      expect(asset.bytes).toBeLessThanOrEqual(budgets.sceneLodMaxBytes);
    }
  });

  it('parses as glTF 2.0 with an animation that targets a real node', () => {
    for (const asset of manifest.assets) {
      const gltf = JSON.parse(readFileSync(join(dir, asset.file), 'utf8')) as {
        asset: { version: string };
        nodes: readonly { name?: string }[];
        animations: readonly { name: string; channels: readonly { target: { node: number } }[] }[];
      };
      expect(gltf.asset.version).toBe('2.0');
      const clip = gltf.animations.find((a) => a.name === asset.clip);
      expect(clip).toBeDefined();
      for (const channel of clip!.channels) {
        expect(gltf.nodes[channel.target.node]).toBeDefined();
      }
    }
  });
});
